  '</div><div class="nav-actions"><button type="button" id="navAccount" class="nav-quiet nav-account" data-go="account">'+esc(window.MindGardenAccount?.navLabel()||T('Sign in','登录'))+'</button><button class="nav-quiet nav-symbol" data-go="music" aria-label="'+T('Music','音乐')+'">'+icon('music')+'</button><button class="nav-quiet nav-symbol" data-go="language" aria-label="'+T('Language','语言')+'">'+icon('language')+'</button><button type="button" id="navAppearance" class="nav-quiet nav-symbol nav-appearance" data-go="appearance"></button><button type="button" id="navMore" class="nav-more" aria-controls="navMenu" aria-expanded="false" aria-label="'+T('Open menu','打开菜单')+'">'+icon('menu')+'</button></div><div id="navMenu" class="nav-menu hidden">'+menuGroup('Play','游戏',[['daily','✿','Today’s Games','今日游戏'],['mygames','♡','My Games','我的游戏'],['library','▦','All Games','所有游戏'],['online','♧','Play Together','一起玩'],['progress','▥','My Progress','我的进度'],['leaderboard','♜','Leaderboard','排行榜']])+menuGroup('Player','玩家',[['account','♙','Sign in / Account','登录 / 账户'],['family','♡','Players’ Progress','玩家进度'],['profile','♙','Switch Player','切换玩家']])+'<details class="nav-preferences"><summary>'+T('Preferences','偏好设置')+'</summary>'+menuGroup('Controls','控件',[['music','♫','Music','音乐'],['nature','◖','Background audio','背景声音'],['motion','Ⅱ','Animation','动画'],['language','文','Language','语言'],['settings','⚙','More settings','更多设置']])+'<fieldset class="nav-theme"><legend>'+T('Display mode','显示模式')+'</legend><div class="nav-theme-options">'+[['light',T('Light','浅色')],['dark',T('Dark','深色')],['auto',T('Auto','自动')]].map(v=>'<button type="button" data-mode="'+v[0]+'" aria-pressed="'+((save.mode||'auto')===v[0])+'">'+v[1]+'</button>').join('')+'</div></fieldset></details>'+menuGroup('Help','帮助',[['quickguide','?','Quick guide','快速指南'],['about','ⓘ','About','关于'],['contact','✉','Contact','联系']])+'</div>';
  syncAppearance();window.MindGardenAccount?.refreshUI();
  nav.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>{closeNavMenu();navAction(b.dataset.go)});
  const more=document.getElementById('navMore'),menu=document.getElementById('navMenu');more.onclick=()=>{const isOpen=!menu.classList.toggle('hidden');more.setAttribute('aria-controls','navMenu');more.setAttribute('aria-expanded',String(isOpen));more.setAttribute('aria-label',isOpen?T('Close menu','关闭菜单'):T('Open menu','打开菜单'));if(isOpen)menu.querySelector('button')?.focus()};
