  '<div class="welcome-choice"><button class="welcome-feature feature-games" id="dashBrowse"><span class="feature-icon" aria-hidden="true">'+icon('games')+'</span><strong>'+T('All Games','所有游戏')+'</strong></button>'+info('Explore every activity and choose a difficulty before you begin.','浏览所有活动，开始前选择难度。')+'</div>'+
  '<h2 class="welcome-group-title">'+T('Connect and track progress','互动与进度')+'</h2><div class="welcome-choice"><button class="welcome-feature feature-together" id="dashTogether"><span class="feature-icon" aria-hidden="true">'+icon('together')+'</span><strong>'+T('Play Together','一起玩')+'</strong></button>'+info('Invite family or friends. Choose a session length; every player presses Begin when ready.','邀请家人或朋友。选择回合数，各玩家准备好后点击开始。')+'</div>'+
  [['dashProgress','progress','My Progress','我的进度','See your activity, scores and garden growth.','查看您的活动、成绩和花园成长。'],['dashLeaders','trophy','Leaderboard','排行榜','See rankings and compare game scores.','查看排名并比较游戏成绩。']].map(v=>'<div class="welcome-choice"><button class="welcome-feature" id="'+v[0]+'"><span class="feature-icon" aria-hidden="true">'+icon(v[1])+'</span><strong>'+T(v[2],v[3])+'</strong></button>'+info(v[4],v[5])+'</div>').join('')+'</div><div class="garden-breathing-space" aria-hidden="true"></div></div><p class="dash-disclaimer">'+T('For enjoyment and cognitive engagement. Not a medical test or treatment.','用于娱乐和认知活动，并非医疗测试或治疗。')+'</p>';
  document.getElementById('welcomeName').onclick=()=>window.MindGardenIdentity?.open();
  document.getElementById('dashStart').onclick=startDaily;
  document.getElementById('dashBrowse').onclick=()=>switchPage('library');
  document.getElementById('dashTogether').onclick=()=>navAction('online');
  document.getElementById('dashProgress').onclick=()=>navAction('progress');
  document.getElementById('dashLeaders').onclick=()=>navAction('leaderboard');
