 const prettyCat=c=>T(...(LABELS[c]||LABELS.all));
 function gameCard(k){const m=MG[k],cat=META[k]||'logic',lvl=(me().levels||{})[k]||1,minutes=GAME_TIME[k]||3;
  return '<button class="game-tile" data-game="'+esc(k)+'" data-category="'+cat+'" aria-label="'+esc(m.n)+'"><span class="game-art" aria-hidden="true">'+gamePicture(m.ic)+'</span><span class="game-info"><strong>'+esc(m.n)+'</strong><span class="game-desc">'+esc(m.d)+'</span><span class="game-meta">'+(window.MindGardenCommercial?.has(k)?'':prettyCat(cat)+' · '+minutes+' '+T('min','分钟')+' · ')+(window.MindGardenCommercial?.has(k)?T('Practice preview · scores by level','练习预览 · 按难度保存成绩'):k==='pets'?T('Relaxed play · no scores','轻松互动 · 不计分'):(window.MindGardenActivities?.has(k)||window.MindGardenNewGames?.has(k))?T('3 relaxed choices','3种轻松难度'):T('Level '+lvl+' / 15','第 '+lvl+' / 15 关'))+'</span></span><span class="game-play" aria-hidden="true">▶</span></button>'}
 function renderLibrary(searchOnly=false){
  library.querySelectorAll('.zw,.decks,.levels,.garden,.sub,h2.sec,.tip').forEach(el=>{if(el.closest('#libraryDisplay'))return;el.classList.add('legacy-library')});
  let panel=document.getElementById('libraryDisplay');if(!panel){panel=document.createElement('div');panel.id='libraryDisplay';library.insertBefore(panel,library.firstChild)}
  const keys=Object.keys(MG).filter(k=>((META[k]||'logic')===filter||filter==='all')&&((MG[k].n+' '+MG[k].d+' '+tr(MG[k].n)+' '+tr(MG[k].d)).toLowerCase().includes(search.toLowerCase())));
  const pairs=filter==='all'||filter==='memory';
  const pairMatch=pairs&&('matching pairs memory picture cards 配对游戏 记忆 图片').includes(search.toLowerCase());
  const content='<header class="library-heading"><h1>'+T('Catalog','游戏目录')+'</h1><div class="library-tabs"><button class="btn main" aria-current="page">'+T('All Games','所有游戏')+'</button><button class="btn" id="libraryMyGames">'+T('My Games','我的游戏')+'</button></div></header><div class="game-filterbar"><label class="search-field"><span aria-hidden="true">⌕</span><span class="sr">'+T('Search games','搜索游戏')+'</span><input id="gameSearch" type="search" placeholder="'+T('Search games…','搜索游戏…')+'" value="'+esc(search)+'"></label><label class="library-category">'+T('Category','类别')+' <select id="gameCategory">'+['all',...Object.keys(LABELS).filter(c=>c!=='all').sort((a,b)=>LABELS[a][0].localeCompare(LABELS[b][0],'en'))].map(c=>'<option value="'+c+'"'+(filter===c?' selected':'')+'>'+prettyCat(c)+'</option>').join('')+'</select></label></div><p id="libraryCount" aria-live="polite">'+prettyCat(filter)+' · '+(keys.length+(pairMatch?1:0))+' '+T(keys.length+(pairMatch?1:0)===1?'game':'games','个游戏')+'</p><div id="gameCards" class="game-card-grid">'+(pairMatch?'<button class="game-tile" data-game="pairs"><span class="game-art" aria-hidden="true">'+gamePicture('🌺')+'</span><span class="game-info"><strong>'+T('Matching Pairs','配对游戏')+'</strong><span class="game-desc">'+T('Find the matching picture cards.','找出相同的图片卡片。')+'</span><span class="game-meta">'+T('Memory · 6 levels · relaxed mode available','记忆 · 6关 · 可选轻松模式')+'</span></span><span class="game-play" aria-hidden="true">▶</span></button>':'')+keys.map(gameCard).join('')+'</div>'+(keys.length||pairMatch?'':'<div class="empty-games">🌱 '+T('No games match your search. Try another category or word.','没有找到符合条件的游戏，请换个关键词或类别。')+'</div>')+'<p class="library-foot">'+T('Tap a card to choose settings and play. Tap ⓘ for instructions without starting.','点击卡片选择设置并开始游戏。点击 ⓘ 查看说明，不会启动游戏。')+'</p>';
  if(searchOnly&&document.getElementById('gameCards')){const temp=document.createElement('div');temp.innerHTML=content;document.getElementById('gameCards').replaceWith(temp.querySelector('#gameCards'));panel.querySelector('.empty-games')?.remove();const empty=temp.querySelector('.empty-games');if(empty)document.getElementById('gameCards').after(empty)}else panel.innerHTML=content;
  const input=document.getElementById('gameSearch');input.oninput=e=>{search=input.value;if(!e.isComposing)renderLibrary(true)};input.oncompositionend=()=>{search=input.value;renderLibrary(true)};
  document.getElementById('gameCategory').onchange=e=>{filter=e.target.value;renderLibrary()};
  document.getElementById('libraryMyGames').onclick=()=>window.MindGardenPersonal.myGames();
  document.getElementById('libraryCount').textContent=prettyCat(filter)+' · '+(keys.length+(pairMatch?1:0))+' '+T(keys.length+(pairMatch?1:0)===1?'game':'games','个游戏');
  panel.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;renderLibrary()});
  panel.querySelectorAll('[data-game]').forEach(b=>b.onclick=()=>{const k=b.dataset.game;if(k==='pairs')showPairs();else {window.mgSessionLength=({short:4,standard:6,long:10})[length];window.chooseMiniLevel(k)}});
 }
 function matchingMode(){return '<fieldset class="matching-mode"><legend>'+T('Play mode','游戏模式')+'</legend><div class="row"><button class="btn" data-pair-mode="0" aria-pressed="'+!save.timed+'">'+T('Standard · no time limit','标准 · 不限时')+'</button><button class="btn" data-pair-mode="1" aria-pressed="'+!!save.timed+'">'+T('Timed challenge','限时挑战')+'</button></div><p>'+T('Standard lets you finish at your own pace. Timed adds a countdown and speed stars.','标准模式可按自己的节奏完成。限时模式设倒计时与速度星级。')+'</p></fieldset>'}
 function wireMatchingMode(){document.querySelectorAll('[data-pair-mode]').forEach(b=>b.onclick=()=>{save.timed=Number(b.dataset.pairMode);persist();document.querySelectorAll('[data-pair-mode]').forEach(x=>x.setAttribute('aria-pressed',String(Number(x.dataset.pairMode)===save.timed)))})}
 function showPairs(){const opts=LEVELS.map((v,i)=>'<button class="btn" data-pair-level="'+i+'" '+(i>=save.unlocked?'disabled':'')+'>'+T('Level','第')+' '+(i+1)+(save.lang==='zh'?'关':'')+' · '+v.p+' '+T('pairs','对')+'</button>').join('');
  overlay('<h2>'+T('Matching Pairs','配对游戏')+'</h2><p>'+T('Choose your matching game level.','请选择配对游戏关卡。')+'</p>'+matchingMode()+'<div class="level-buttons">'+opts+'</div><p class="tip">'+T('Unlock additional levels by finishing earlier ones.','完成前面的关卡后可解锁后续关卡。')+'</p><div class="row"><button id="pairBack" class="btn">'+T('Back','返回')+'</button></div>');
  wireMatchingMode();document.querySelectorAll('[data-pair-level]').forEach(b=>b.onclick=()=>start(Number(b.dataset.pairLevel)));
  document.getElementById('pairBack').onclick=closeOv;
 }
 function switchPage(p){page=p;dash.classList.toggle('hidden',p!=='dashboard');progressStrip.classList.toggle('hidden',p!=='dashboard');library.classList.toggle('hidden',p!=='library');top.classList.add('hidden');legacyNav.classList.add('hidden');if(p==='library')renderLibrary();else {renderWelcome();renderProgress()}buildNav();window.scrollTo({top:0,behavior:'instant'})}
 const oldShow=window.show;window.show=function(which){oldShow(which);if(which==='home'&&daily)daily=null;nav.classList.toggle('hidden',which!=='home');if(which==='home')switchPage(page)};
 const oldRender=window.renderHome;window.renderHome=function(){oldRender();if(page==='dashboard'){renderWelcome();renderProgress()}else renderLibrary();buildNav()};
 function dailyGame(type){return type==='pairs'?{n:T('Matching Pairs','配对游戏'),d:T('Find the matching picture cards.','找出相同的图片卡片。')}:MG[type]}
 function startDaily(){const plan=window.MindGardenPractice.select(me(),['pairs',...Object.keys(MG).filter(k=>!['pets','today','localnews','gardenrhythm','followgardener'].includes(k)&&!window.MindGardenCommercial?.has(k))],today());daily={plan,types:plan.map(x=>x.type),index:0,active:false};dailyIntro()}
 function dailyIntro(){if(!daily)return;const idx=daily.index,item=daily.plan[idx],type=item.type,m=dailyGame(type),max=window.MindGardenPersonal?window.MindGardenPersonal.settings(type).count:type==='pairs'?6:(window.MindGardenNewGames.has(type)||window.MindGardenActivities?.has(type))?3:15,recommended=type==='pairs'?Math.min(6,me().unlocked||1):Math.min(max,Math.max(1,Math.round(me().levels?.[type]||1)));
  const reason=item.samples?T('Practice focus: '+Math.round(item.average*100)+'% average result across your last '+item.samples+' completed session'+(item.samples>1?'s':'')+' in this game.','练习重点：此游戏最近'+item.samples+'局的平均成绩为'+Math.round(item.average*100)+'%。'):T('We are building your history. This activity adds variety until more results are available.','正在建立您的记录。在获得更多成绩之前，用此活动丰富练习。');
  overlay('<p class="daily-progress">'+T('Activity','活动')+' '+(idx+1)+' / 3</p><h2>'+esc(m.n)+'</h2><p>'+esc(m.d)+'</p><p class="daily-reason">'+esc(reason)+'</p><label class="lab">'+T('Practice level','练习难度')+'<select id="dailyDifficulty">'+Array.from({length:max},(_,i)=>'<option value="'+(i+1)+'"'+(i+1===recommended?' selected':'')+'>'+T('Level ','第 ')+(i+1)+T('',' 关')+'</option>').join('')+'</select></label>'+(type==='pairs'?matchingMode():'')+'<p>'+T('Take your time. You can choose an easier level or finish early.','慢慢来，可以选择较简单的难度或提前结束。')+'</p><div class="row"><button class="btn main" id="dailyGo">'+T('Begin','开始')+'</button><button class="btn" id="dailyStop">'+T('Finish for now','暂时结束')+'</button></div>');
  if(type==='pairs')wireMatchingMode();document.getElementById('dailyGo').onclick=()=>{const chosen=Number(document.getElementById('dailyDifficulty').value);daily.active=true;if(window.MindGardenPersonal){window.MindGardenPersonal.setup(type,chosen);return}window.mgSessionLength=6;window.mgDifficulty=chosen;if(type==='pairs'){mg=null;start(chosen-1);window.scrollTo(0,0)}else startMG(type)};
  document.getElementById('dailyStop').onclick=()=>{daily=null;mg=null;closeOv();toHome();switchPage('dashboard')};
 }
 function completeDaily(type){if(window.MindGardenPersonal?.session?.practice)return false;if(!daily||!daily.active||daily.types[daily.index]!==type)return false;daily.active=false;const completed=daily.index+1;
  if(completed===3){daily=null;overlay('<p class="daily-progress">🌻 '+T('Daily journey complete','今日活动完成')+'</p><h2>'+T('Wonderful work!','做得真棒！')+'</h2><p>'+T('You completed three different activities. Enjoy a rest or browse more games.','您完成了三项不同的活动，可以休息或探索更多游戏。')+'</p><div class="row"><button class="btn main" id="dailyHome">'+T('Return to my garden','返回花园')+'</button></div>');document.getElementById('dailyHome').onclick=()=>{mg=null;toHome();switchPage('dashboard')}}
  else{daily.index++;overlay('<p class="daily-progress">✓ '+completed+'/3 '+T('completed','已完成')+'</p><h2>'+T('Well done!','做得好！')+'</h2><p>'+T('Next activity: ','下一项：')+esc(dailyGame(daily.types[daily.index]).n)+'</p><div class="row"><button class="btn main" id="dailyNext">'+T('Next activity','下一项')+'</button><button class="btn" id="dailyRest">'+T('Finish for today','今日结束')+'</button></div>');document.getElementById('dailyNext').onclick=dailyIntro;document.getElementById('dailyRest').onclick=()=>{daily=null;mg=null;toHome();switchPage('dashboard')}}
  return true;
 }
